import React, { useState, useEffect, useCallback } from 'react';
import api from './api';

/* ─── Design tokens ──────────────────────────────────────────────────────── */
const G = {
  bg:'#0A0A0A', card:'#111111', card2:'#181818', card3:'#1C1C1C',
  border:'#1E1E1E', border2:'#252525', border3:'#2C2C2C',
  green:'#22C55E', greenDark:'#16A34A', greenBg:'#052E1C', greenBdr:'#166534',
  text:'#EEEEEE', text2:'#999999', text3:'#555555',
  red:'#EF4444', redBg:'#200A0A', redBdr:'#450A0A',
  amber:'#F59E0B', amberBg:'#2D1F00',
  purple:'#818CF8', purpleBg:'#1A1040', purpleBdr:'#2D1A50',
  blue:'#38BDF8', blueBg:'#0A1A2D',
};

const css = {
  app:       { minHeight:'100vh', background:G.bg, color:G.text, fontFamily:"'Inter',sans-serif", fontSize:14 },
  center:    { display:'flex', alignItems:'center', justifyContent:'center', minHeight:'100vh', padding:16 },
  col:       { display:'flex', flexDirection:'column', gap:12 },
  row:       { display:'flex', alignItems:'center', gap:8 },
  card:      { background:G.card, border:`1px solid ${G.border}`, borderRadius:16, padding:20 },
  card2:     { background:G.card2, border:`1px solid ${G.border2}`, borderRadius:12, padding:16 },
  authWrap:  { width:'100%', maxWidth:400 },
  brand:     { textAlign:'center', marginBottom:32 },
  brandIcon: { width:72, height:72, borderRadius:20, background:G.greenBg, display:'flex', alignItems:'center', justifyContent:'center', fontSize:32, margin:'0 auto 16px', border:`1px solid ${G.greenBdr}` },
  brandName: { fontSize:32, fontWeight:900, color:G.green, letterSpacing:0.5 },
  label:     { fontSize:11, fontWeight:700, color:G.text3, textTransform:'uppercase', letterSpacing:0.8, marginBottom:6, display:'block' },
  input:     { width:'100%', background:G.card2, border:`1px solid ${G.border2}`, borderRadius:10, padding:'13px 14px', fontSize:15, color:G.text, outline:'none', boxSizing:'border-box' },
  btn:       { width:'100%', background:G.greenDark, color:'#fff', border:'none', borderRadius:10, padding:'15px 20px', fontSize:16, fontWeight:700, cursor:'pointer' },
  btnSm:     { background:G.greenDark, color:'#fff', border:'none', borderRadius:8, padding:'10px 18px', fontSize:13, fontWeight:600, cursor:'pointer' },
  btnGhost:  { background:'transparent', color:G.text2, border:`1px solid ${G.border2}`, borderRadius:8, padding:'10px 18px', fontSize:13, fontWeight:600, cursor:'pointer' },
  link:      { color:G.green, cursor:'pointer', fontWeight:600 },
  linkText:  { fontSize:13, color:G.text3, textAlign:'center' },
  err:       { background:G.redBg, border:`1px solid ${G.redBdr}`, borderRadius:8, padding:'10px 14px', fontSize:13, color:G.red },
  ok:        { background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:8, padding:'10px 14px', fontSize:13, color:G.green },
  nav:       { background:'#0F0F0F', borderBottom:`1px solid ${G.border}`, padding:'0 20px', display:'flex', alignItems:'center', justifyContent:'space-between', height:56, position:'sticky', top:0, zIndex:100 },
  navBrand:  { fontSize:20, fontWeight:900, color:G.green },
  tabBar:    { position:'fixed', bottom:0, left:0, right:0, background:'#0F0F0F', borderTop:`1px solid ${G.border}`, display:'flex', zIndex:100 },
  tabItem:   { flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'10px 0', cursor:'pointer', fontSize:10, fontWeight:600, gap:4 },
  page:      { maxWidth:480, margin:'0 auto', padding:'20px 16px 90px' },
  pageTitle: { fontSize:26, fontWeight:800, color:G.text, marginBottom:20 },
  sectionLabel: { fontSize:11, fontWeight:700, color:G.text3, textTransform:'uppercase', letterSpacing:0.8, marginBottom:10, display:'block' },
  badge:     { borderRadius:20, padding:'3px 10px', fontSize:10, fontWeight:700, display:'inline-block' },
  divider:   { height:1, background:G.border, margin:'12px 0' },
  backBtn:   { background:'none', border:'none', color:G.green, cursor:'pointer', fontSize:14, fontWeight:600, marginBottom:20, padding:0, display:'flex', alignItems:'center', gap:4 },
};

const STATUS_STYLE = {
  pending_payment: { bg:G.amberBg,   color:G.amber,   label:'Awaiting payment', icon:'💳' },
  queued:          { bg:G.purpleBg,  color:G.purple,  label:'In queue',         icon:'⏳' },
  printing:        { bg:G.greenBg,   color:G.green,   label:'Printing…',        icon:'🖨️' },
  ready:           { bg:G.greenBg,   color:G.green,   label:'Ready for pickup', icon:'✅' },
  collected:       { bg:'#1A1A1A',   color:G.text3,   label:'Collected',        icon:'📦' },
  cancelled:       { bg:G.redBg,     color:G.red,     label:'Cancelled',        icon:'❌' },
  failed:          { bg:G.redBg,     color:G.red,     label:'Failed',           icon:'⚠️' },
};

/* ─── Shared helpers ─────────────────────────────────────────────────────── */
function Spinner() {
  return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', padding:40 }}>
      <div style={{ width:32, height:32, border:`3px solid ${G.border}`, borderTop:`3px solid ${G.green}`, borderRadius:'50%', animation:'spin 0.8s linear infinite' }}/>
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

function Alert({ msg, type='error' }) {
  if (!msg) return null;
  return <div style={type==='error' ? css.err : css.ok}>{msg}</div>;
}

function BackBtn({ onClick, label='← Back' }) {
  return <button style={css.backBtn} onClick={onClick}>{label}</button>;
}

function Divider() { return <div style={css.divider}/>; }

function TabBar({ active, onNav }) {
  const tabs = [
    { id:'home',  icon:'🏠', label:'Home'    },
    { id:'jobs',  icon:'📄', label:'My Jobs' },
    { id:'shops', icon:'📍', label:'Shops'   },
    { id:'profile',icon:'👤',label:'Profile' },
  ];
  return (
    <div style={css.tabBar}>
      {tabs.map(t => (
        <div key={t.id}
          style={{ ...css.tabItem, color: active===t.id ? G.green : G.text3 }}
          onClick={() => onNav(t.id)}>
          <span style={{ fontSize:20 }}>{t.icon}</span>
          <span>{t.label}</span>
        </div>
      ))}
    </div>
  );
}

/* ─── Row util for cost/detail rows ─────────────────────────────────────── */
function InfoRow({ label, value, accent }) {
  return (
    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', padding:'6px 0', borderBottom:`1px solid ${G.border}` }}>
      <span style={{ fontSize:13, color:G.text3 }}>{label}</span>
      <span style={{ fontSize:13, fontWeight:600, color: accent || G.text }}>{value}</span>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   AUTH SCREENS
══════════════════════════════════════════════════════════════════════════ */
function LoginScreen({ onLogin, onGoRegister }) {
  const [phone,    setPhone]    = useState('');
  const [password, setPassword] = useState('');
  const [err,      setErr]      = useState('');
  const [loading,  setLoading]  = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (!phone || !password) { setErr('Phone and password are required'); return; }
    setLoading(true); setErr('');
    try {
      const { data } = await api.post('/auth/login/', { phone, password });
      localStorage.setItem('token', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      onLogin(data.user);
    } catch(e) {
      setErr(e.response?.data?.error || 'Login failed');
    } finally { setLoading(false); }
  };

  return (
    <div style={css.center}>
      <div style={css.authWrap}>
        <div style={css.brand}>
          <div style={css.brandIcon}>🖨️</div>
          <div style={css.brandName}>PrintShop</div>
          <div style={{ fontSize:13, color:G.text3, marginTop:6 }}>Print anywhere. Pay once. Collect on the way.</div>
        </div>
        <div style={css.card}>
          <div style={{ fontSize:22, fontWeight:800, color:G.text, marginBottom:20 }}>Sign in</div>
          <form onSubmit={submit} style={css.col}>
            <div>
              <label style={css.label}>Phone number</label>
              <input style={css.input} placeholder="10-digit mobile" type="tel" maxLength={10}
                value={phone} onChange={e => setPhone(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Password</label>
              <input style={css.input} placeholder="Your password" type="password"
                value={password} onChange={e => setPassword(e.target.value)}/>
            </div>
            <Alert msg={err}/>
            <button type="submit" style={{ ...css.btn, opacity: loading ? 0.6 : 1 }} disabled={loading}>
              {loading ? 'Signing in…' : 'Sign in'}
            </button>
            <div style={css.linkText}>
              No account? <span style={css.link} onClick={onGoRegister}>Sign up</span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

function RegisterScreen({ onLogin, onGoLogin }) {
  const [name,     setName]     = useState('');
  const [phone,    setPhone]    = useState('');
  const [password, setPassword] = useState('');
  const [confirm,  setConfirm]  = useState('');
  const [err,      setErr]      = useState('');
  const [loading,  setLoading]  = useState(false);
  const [success,  setSuccess]  = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    if (!name || !phone || !password || !confirm) { setErr('All fields are required'); return; }
    if (password !== confirm)    { setErr('Passwords do not match'); return; }
    if (password.length < 6)     { setErr('Password must be at least 6 characters'); return; }
    if (!/^\d{10}$/.test(phone)) { setErr('Enter a valid 10-digit phone number'); return; }
    setLoading(true); setErr('');
    try {
      const { data } = await api.post('/auth/register/', { name, phone, password });
      localStorage.setItem('token', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      setSuccess(data.user);
    } catch(e) {
      setErr(e.response?.data?.error || 'Registration failed');
    } finally { setLoading(false); }
  };

  if (success) {
    return (
      <div style={css.center}>
        <div style={{ ...css.authWrap, textAlign:'center' }}>
          <div style={css.card}>
            <div style={{ fontSize:48, marginBottom:16 }}>🎉</div>
            <div style={{ fontSize:22, fontWeight:800, color:G.text, marginBottom:8 }}>Account created!</div>
            <div style={{ fontSize:13, color:G.text3, marginBottom:24 }}>Your permanent PrintShop ID</div>
            <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:16, padding:24, marginBottom:16 }}>
              <div style={{ fontSize:11, color:'#4ADE80', marginBottom:8 }}>YOUR ID (show at counter)</div>
              <div style={{ fontSize:56, fontWeight:900, color:G.green, letterSpacing:10 }}>{success.short_id}</div>
              <div style={{ fontSize:14, color:'#4ADE80', marginTop:8 }}>{success.name}</div>
            </div>
            <div style={{ background:G.purpleBg, border:`1px solid ${G.purpleBdr}`, borderRadius:12, padding:16, marginBottom:20 }}>
              <div style={{ fontSize:11, color:'#A78BFA', marginBottom:6 }}>YOUR PICKUP CODE (say at counter)</div>
              <div style={{ fontSize:36, fontWeight:900, color:G.purple, letterSpacing:8 }}>{success.pickup_code}</div>
            </div>
            <div style={{ fontSize:12, color:G.text3, marginBottom:20 }}>
              📸 Screenshot this — you'll need the code to collect printouts
            </div>
            <button style={css.btn} onClick={() => onLogin(success)}>Continue to app →</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={css.center}>
      <div style={css.authWrap}>
        <div style={css.brand}>
          <div style={css.brandIcon}>🖨️</div>
          <div style={css.brandName}>PrintShop</div>
        </div>
        <div style={css.card}>
          <div style={{ fontSize:22, fontWeight:800, color:G.text, marginBottom:20 }}>Create account</div>
          <form onSubmit={submit} style={css.col}>
            <div>
              <label style={css.label}>Full name</label>
              <input style={css.input} placeholder="Your name" value={name} onChange={e => setName(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Phone number</label>
              <input style={css.input} placeholder="10-digit mobile" type="tel" maxLength={10}
                value={phone} onChange={e => setPhone(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Password</label>
              <input style={css.input} placeholder="Min 6 characters" type="password"
                value={password} onChange={e => setPassword(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Confirm password</label>
              <input style={css.input} placeholder="Repeat password" type="password"
                value={confirm} onChange={e => setConfirm(e.target.value)}/>
            </div>
            <Alert msg={err}/>
            <button type="submit" style={{ ...css.btn, opacity: loading ? 0.6 : 1 }} disabled={loading}>
              {loading ? 'Creating account…' : 'Create account'}
            </button>
            <div style={css.linkText}>
              Already have an account? <span style={css.link} onClick={onGoLogin}>Sign in</span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   HOME
══════════════════════════════════════════════════════════════════════════ */
function HomeScreen({ user, onNav }) {
  const [jobs, setJobs] = useState([]);

  useEffect(() => {
    api.get('/jobs/').then(r => setJobs(r.data.jobs || [])).catch(() => {});
  }, []);

  const active = jobs.filter(j => !['collected','cancelled','failed'].includes(j.status));

  return (
    <div style={css.page}>
      {/* Welcome card */}
      <div style={{ ...css.card, marginBottom:16, background:'#0D2D1F', border:`1px solid ${G.greenBdr}`, display:'flex', alignItems:'center', justifyContent:'space-between' }}>
        <div>
          <div style={{ fontSize:20, fontWeight:800, color:G.text }}>Hello, {user.name.split(' ')[0]} 👋</div>
          <div style={{ fontSize:13, color:'#4ADE80', marginTop:4 }}>
            ID: <strong style={{ letterSpacing:2 }}>{user.short_id}</strong>
          </div>
        </div>
        <button style={{ ...css.btnSm, background:'rgba(255,255,255,0.1)' }} onClick={() => onNav('pickupid')}>
          Show ID
        </button>
      </div>

      {/* New print CTA */}
      <div style={{ background:G.greenDark, borderRadius:16, padding:20, marginBottom:20, display:'flex', alignItems:'center', justifyContent:'space-between', cursor:'pointer', border:`1px solid #166534` }}
        onClick={() => onNav('newjob')}>
        <div style={css.row}>
          <span style={{ fontSize:28 }}>🖨️</span>
          <div>
            <div style={{ fontSize:17, fontWeight:700, color:'#fff' }}>New print job</div>
            <div style={{ fontSize:12, color:'rgba(255,255,255,0.6)', marginTop:2 }}>Upload · Pay · Collect</div>
          </div>
        </div>
