/* ═══════════════════════════════════════════════════════════════════════════
   NEW JOB — configure preferences only, then go to checkout
══════════════════════════════════════════════════════════════════════════ */
function NewJobScreen({ onNav }) {
  const [shops,       setShops]       = useState([]);
  const [shopId,      setShopId]      = useState('');
  const [fileName,    setFileName]    = useState('');
  const [pages,       setPages]       = useState(1);
  const [colorMode,   setColorMode]   = useState('bw');
  const [paperSize,   setPaperSize]   = useState('A4');
  const [copies,      setCopies]      = useState(1);
  const [doubleSided, setDoubleSided] = useState(false);
  const [amount,      setAmount]      = useState(0);
  const [err,         setErr]         = useState('');

  useEffect(() => {
    api.get('/shops/nearby/').then(r => setShops(r.data.shops || [])).catch(() => {});
  }, []);

  // Live cost calculation (mirrors views.py)
  useEffect(() => {
    const RATES = { bw: {A4:1.5,A3:2.25,Letter:1.5}, color: {A4:7,A3:10.5,Letter:7} };
    const rate  = (RATES[colorMode] || RATES.bw)[paperSize] || 1.5;
    setAmount(+(rate * pages * copies * (doubleSided ? 0.8 : 1)).toFixed(2));
  }, [pages, colorMode, paperSize, copies, doubleSided]);

  const proceedToCheckout = () => {
    if (!shopId)   { setErr('Please select a shop'); return; }
    if (!fileName) { setErr('Please enter a document name'); return; }
    if (pages < 1) { setErr('Pages must be at least 1'); return; }
    setErr('');
    const selectedShop = shops.find(s => s.id === shopId);
    onNav('checkout', {
      shopId, fileName, pages, colorMode, paperSize, copies,
      doubleSided, amount, shop: selectedShop
    });
  };

  const chip = (val, cur, set, label) => (
    <button key={val} onClick={() => set(val)}
      style={{ padding:'8px 16px', borderRadius:8, border:`1.5px solid ${cur===val ? G.green : G.border2}`,
        background: cur===val ? G.greenBg : G.card2, color: cur===val ? G.green : G.text2,
        cursor:'pointer', fontWeight:600, fontSize:13 }}>
      {label}
    </button>
  );

  const counter = (val, set, min=1, max=999) => (
    <div style={css.row}>
      <button style={{ width:36, height:36, borderRadius:18, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:20, fontWeight:300 }}
        onClick={() => set(v => Math.max(min, v-1))}>−</button>
      <span style={{ fontSize:18, fontWeight:700, color:G.text, minWidth:40, textAlign:'center' }}>{val}</span>
      <button style={{ width:36, height:36, borderRadius:18, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:20, fontWeight:300 }}
        onClick={() => set(v => Math.min(max, v+1))}>+</button>
    </div>
  );

  return (
    <div style={css.page}>
      <BackBtn onClick={() => onNav('home')}/>
      <div style={css.pageTitle}>New print job</div>
      <div style={css.col}>

        {/* Document name */}
        <div style={css.card}>
          <label style={css.label}>Document name</label>
          <input style={css.input} value={fileName} onChange={e => setFileName(e.target.value)}
            placeholder="e.g. resume.pdf, assignment.pdf"/>
        </div>

        {/* Shop selection */}
        <div style={css.card}>
          <label style={css.label}>Print shop</label>
          {shops.length === 0 ? (
            <div style={{ color:G.text3, fontSize:13, padding:'8px 0' }}>No shops online right now</div>
          ) : shops.map(s => (
            <div key={s.id} onClick={() => setShopId(s.id)}
              style={{ background: shopId===s.id ? G.greenBg : G.card2,
                border:`1.5px solid ${shopId===s.id ? G.green : G.border2}`,
                borderRadius:10, padding:12, cursor:'pointer', marginBottom:6 }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                <div style={{ fontWeight:700, color:G.text }}>{s.name}</div>
                <span style={{ ...css.badge, background: s.is_online ? G.greenBg : '#1A1A1A', color: s.is_online ? G.green : G.text3 }}>
                  {s.is_online ? '● Online' : '○ Offline'}
                </span>
              </div>
              <div style={{ fontSize:12, color:G.text3, marginTop:2 }}>{s.address}</div>
              <div style={{ display:'flex', justifyContent:'space-between', marginTop:6, fontSize:12 }}>
                <span style={{ color: s.queue_length >= 18 ? G.red : s.queue_length >= 14 ? G.amber : G.text3 }}>
                  Queue: {s.queue_length}/20 {s.queue_length >= 20 ? '🔴 Full' : s.queue_length >= 14 ? '🟡 Busy' : '🟢'}
                </span>
                <span style={{ color:G.text3 }}>⏰ {s.opens_at}–{s.closes_at}</span>
              </div>
              {shopId===s.id && <div style={{ fontSize:12, color:G.green, marginTop:6, fontWeight:600 }}>✓ Selected</div>}
            </div>
          ))}
        </div>

        {/* Preferences */}
        <div style={css.card}>
          <label style={css.label}>Preferences</label>

          <div style={{ marginBottom:14 }}>
            <div style={{ fontSize:12, color:G.text3, marginBottom:8 }}>Color mode</div>
            <div style={css.row}>
              {chip('bw',    colorMode, setColorMode, '⬛ Black & White')}
              {chip('color', colorMode, setColorMode, '🎨 Color')}
            </div>
          </div>

          <div style={{ marginBottom:14 }}>
            <div style={{ fontSize:12, color:G.text3, marginBottom:8 }}>Paper size</div>
            <div style={css.row}>
              {['A4','A3','Letter'].map(s => chip(s, paperSize, setPaperSize, s))}
            </div>
          </div>

          <div style={{ ...css.row, marginBottom:14, alignItems:'flex-start' }}>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:12, color:G.text3, marginBottom:8 }}>Pages</div>
              {counter(pages, setPages, 1, 999)}
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:12, color:G.text3, marginBottom:8 }}>Copies</div>
              {counter(copies, setCopies, 1, 50)}
            </div>
          </div>

          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:G.card2, padding:14, borderRadius:10 }}>
            <div>
              <div style={{ fontWeight:600, color:G.text, fontSize:14 }}>Double-sided</div>
              <div style={{ fontSize:12, color:G.text3 }}>Save 20% on printing</div>
            </div>
            <div onClick={() => setDoubleSided(d => !d)}
              style={{ width:48, height:26, borderRadius:13, background: doubleSided ? G.greenDark : G.card2, border:`1px solid ${doubleSided ? G.green : G.border2}`, position:'relative', cursor:'pointer', transition:'background 0.2s' }}>
              <div style={{ position:'absolute', top:3, left: doubleSided ? 22 : 3, width:20, height:20, borderRadius:10, background:'#fff', transition:'left 0.2s' }}/>
            </div>
          </div>
        </div>

        {/* Live cost estimate */}
        <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:14, padding:20, textAlign:'center' }}>
          <div style={{ fontSize:12, color:'#4ADE80', marginBottom:4 }}>Estimated total</div>
          <div style={{ fontSize:42, fontWeight:900, color:G.green }}>₹{amount}</div>
          <div style={{ fontSize:12, color:'#4ADE80', marginTop:4 }}>
            {pages}p × {copies} {copies===1?'copy':'copies'} × {colorMode==='color'?'color':'B&W'}{doubleSided?' (duplex)':''}
          </div>
        </div>

        <Alert msg={err}/>

        <button style={{ ...css.btn, opacity: !shopId || !fileName ? 0.5 : 1 }}
          onClick={proceedToCheckout} disabled={!shopId || !fileName}>
          Continue to checkout →
        </button>

      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   CHECKOUT — review order, confirm, and create job
══════════════════════════════════════════════════════════════════════════ */
function CheckoutScreen({ params, user, onNav }) {
  const { shopId, fileName, pages, colorMode, paperSize, copies,
          doubleSided, amount, shop } = params;

  const [loading, setLoading] = useState(false);
  const [err,     setErr]     = useState('');
  const [success, setSuccess] = useState(null);

  // Verify cost server-side before confirming
  const [verifiedAmount, setVerifiedAmount] = useState(amount);
  useEffect(() => {
    api.post('/jobs/calculate-cost/', { pages, color_mode:colorMode, paper_size:paperSize, copies, double_sided:doubleSided })
      .then(r => setVerifiedAmount(r.data.amount))
      .catch(() => {});
  }, []);

  const confirmOrder = async () => {
    setLoading(true); setErr('');
    try {
      const { data } = await api.post('/jobs/create/', {
        shop_id:     shopId,
        file_name:   fileName,
        pages,
        color_mode:  colorMode,
        paper_size:  paperSize,
        copies,
        double_sided: doubleSided,
      });
      setSuccess(data.job);
    } catch(e) {
      const msg = e.response?.data?.error || 'Failed to create job';
      setErr(msg);
    } finally { setLoading(false); }
  };

  /* ── Order placed success screen ── */
  if (success) {
    return (
      <div style={css.page}>
        <div style={{ textAlign:'center', padding:'40px 0 20px' }}>
          <div style={{ fontSize:64, marginBottom:16 }}>✅</div>
          <div style={{ fontSize:26, fontWeight:900, color:G.green, marginBottom:8 }}>Order placed!</div>
          <div style={{ fontSize:14, color:G.text3, marginBottom:32 }}>Your job is in the queue</div>
        </div>

        {/* Job summary */}
        <div style={{ ...css.card, marginBottom:12 }}>
          <span style={css.label}>Job summary</span>
          <InfoRow label="Document"   value={success.file_name}/>
          <InfoRow label="Shop"       value={shop?.name || '—'}/>
          <InfoRow label="Status"     value="In queue" accent={G.purple}/>
          <InfoRow label="Amount paid"value={`₹${success.amount}`} accent={G.green}/>
        </div>

        {/* Pickup reminder */}
        <div style={{ background:G.purpleBg, border:`1px solid ${G.purpleBdr}`, borderRadius:14, padding:20, marginBottom:12 }}>
          <div style={{ fontSize:13, fontWeight:700, color:G.purple, marginBottom:12 }}>How to collect</div>
          {[
            'Go to the print shop when your job is ready',
            `Tell shopkeeper your ID: ${user.short_id}`,
            `Give your pickup code when asked`,
            'Collect your printout ✓',
