          <div style={{ fontSize:11, color:'#4ADE80', marginBottom:6 }}>YOUR PICKUP CODE</div>
          <div style={{ fontSize:40, fontWeight:900, color:G.green, letterSpacing:8 }}>{user.pickup_code}</div>
        </div>

