/* ═══════════════════════════════════════════════════════════════════════════
   JOB DETAIL — live order tracker
══════════════════════════════════════════════════════════════════════════ */
function JobDetailScreen({ job: initialJob, user, onNav }) {
  const [job,     setJob]     = useState(initialJob);
  const [loading, setLoading] = useState(false);
  const [msg,     setMsg]     = useState('');
  const [cancelling, setCancelling] = useState(false);

  // Poll for status updates every 8 seconds for active jobs
  useEffect(() => {
    if (['collected','cancelled','failed'].includes(job.status)) return;
    const poll = setInterval(() => {
      api.get(`/jobs/${job.id}/`)
        .then(r => setJob(r.data))
        .catch(() => {});
    }, 8000);
    return () => clearInterval(poll);
  }, [job.id, job.status]);

  const cancelJob = async () => {
    if (!window.confirm('Cancel this job?')) return;
    setCancelling(true); setMsg('');
    try {
      await api.post(`/jobs/${job.id}/cancel/`);
      setJob(prev => ({ ...prev, status:'cancelled' }));
      setMsg('Job cancelled. Full refund if already paid.');
    } catch(e) {
      setMsg(e.response?.data?.error || 'Could not cancel');
    } finally { setCancelling(false); }
  };

  const st = STATUS_STYLE[job.status] || STATUS_STYLE.queued;

  // Tracker steps
  const STEPS = [
    { key:'pending_payment', label:'Order placed',     icon:'📝', done: true },
    { key:'queued',          label:'In print queue',   icon:'⏳', done: ['queued','printing','ready','collected'].includes(job.status) },
    { key:'printing',        label:'Printing',         icon:'🖨️', done: ['printing','ready','collected'].includes(job.status) },
    { key:'ready',           label:'Ready for pickup', icon:'✅', done: ['ready','collected'].includes(job.status) },
    { key:'collected',       label:'Collected',        icon:'📦', done: job.status === 'collected' },
  ];

  const canCancel = ['pending_payment','queued'].includes(job.status);

  return (
    <div style={css.page}>
      <BackBtn onClick={() => onNav('jobs')}/>

      {/* Header */}
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:20 }}>
        <div>
          <div style={{ fontSize:22, fontWeight:800, color:G.text }}>{job.file_name}</div>
          <div style={{ fontSize:13, color:G.text3, marginTop:4 }}>₹{job.amount} · {job.pages}p · {job.copies} copy</div>
        </div>
        <span style={{ ...css.badge, background:st.bg, color:st.color, fontSize:12, padding:'5px 12px' }}>
          {st.icon} {st.label}
        </span>
      </div>

      {/* Live tracker */}
      {!['cancelled','failed'].includes(job.status) && (
        <div style={{ ...css.card, marginBottom:12 }}>
          <span style={css.label}>Order tracker</span>
          {STEPS.map((step, i) => {
            const isActive  = job.status === step.key;
            const isDone    = step.done && !isActive;
            const isWaiting = !step.done && !isActive;
            return (
              <div key={step.key} style={{ display:'flex', gap:14, alignItems:'flex-start', marginBottom: i < STEPS.length-1 ? 0 : 0 }}>
                {/* Connector line + dot */}
                <div style={{ display:'flex', flexDirection:'column', alignItems:'center', width:28 }}>
                  <div style={{
                    width:28, height:28, borderRadius:14,
                    background: isActive ? G.greenDark : isDone ? G.greenBg : G.card2,
                    border: `2px solid ${isActive ? G.green : isDone ? G.greenBdr : G.border2}`,
                    display:'flex', alignItems:'center', justifyContent:'center',
                    fontSize: isActive ? 14 : 12,
                    flexShrink:0,
                  }}>
                    {isDone ? '✓' : isActive ? step.icon : <span style={{ color:G.text3, fontSize:10 }}>{i+1}</span>}
                  </div>
                  {i < STEPS.length-1 && (
                    <div style={{ width:2, flex:1, minHeight:24, background: isDone ? G.greenBdr : G.border, marginTop:2, marginBottom:2 }}/>
                  )}
                </div>
                {/* Label */}
                <div style={{ paddingTop:4, paddingBottom: i < STEPS.length-1 ? 16 : 0 }}>
                  <div style={{ fontSize:14, fontWeight: isActive ? 700 : 500, color: isActive ? G.green : isDone ? G.text : G.text3 }}>
                    {step.label}
                  </div>
                  {isActive && (
                    <div style={{ fontSize:12, color:'#4ADE80', marginTop:2 }}>
                      {step.key === 'printing' ? '🖨️ Printing in progress…' :
                       step.key === 'ready'    ? '🏪 Head to the shop!' :
                       step.key === 'queued'   ? `📋 In queue` : ''}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Ready for pickup — show codes */}
      {job.status === 'ready' && (
        <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:14, padding:20, marginBottom:12, textAlign:'center' }}>
          <div style={{ fontSize:14, color:'#4ADE80', fontWeight:700, marginBottom:16 }}>🎉 Your printout is ready!</div>
          <div style={{ display:'flex', gap:12 }}>
            <div style={{ flex:1, background:'rgba(0,0,0,0.3)', borderRadius:10, padding:14 }}>
              <div style={{ fontSize:10, color:'#4ADE80', marginBottom:6 }}>SHOW THIS ID</div>
              <div style={{ fontSize:28, fontWeight:900, color:G.green, letterSpacing:4 }}>{user.short_id}</div>
            </div>
            <div style={{ flex:1, background:G.purpleBg, borderRadius:10, padding:14 }}>
              <div style={{ fontSize:10, color:'#A78BFA', marginBottom:6 }}>SAY THIS CODE</div>
              <div style={{ fontSize:28, fontWeight:900, color:G.purple, letterSpacing:4 }}>{user.pickup_code}</div>
            </div>
          </div>
        </div>
      )}

      {/* Order details */}
      <div style={{ ...css.card, marginBottom:12 }}>
        <span style={css.label}>Job details</span>
        <InfoRow label="Color mode"   value={job.color_mode==='bw'?'Black & White':'Color'}/>
        <InfoRow label="Paper size"   value={job.paper_size}/>
        <InfoRow label="Copies"       value={String(job.copies)}/>
        <InfoRow label="Double-sided" value={job.double_sided?'Yes':'No'}/>
        <InfoRow label="Amount"       value={`₹${job.amount}`} accent={G.green}/>
        {job.created_at && (
          <InfoRow label="Created" value={new Date(job.created_at).toLocaleString('en-IN')}/>
        )}
      </div>

      {/* Cancelled / failed state */}
      {job.status === 'cancelled' && (
        <div style={{ background:G.redBg, border:`1px solid ${G.redBdr}`, borderRadius:12, padding:16, marginBottom:12 }}>
          <div style={{ color:G.red, fontWeight:700, marginBottom:4 }}>❌ Job cancelled</div>
          <div style={{ fontSize:13, color:G.text3 }}>Full refund processed if payment was made.</div>
        </div>
      )}
      {job.status === 'failed' && (
        <div style={{ background:G.redBg, border:`1px solid ${G.redBdr}`, borderRadius:12, padding:16, marginBottom:12 }}>
          <div style={{ color:G.red, fontWeight:700, marginBottom:4 }}>⚠️ Print failed</div>
          <div style={{ fontSize:13, color:G.text3 }}>Full refund will be processed within 1 hour.</div>
        </div>
      )}

      {msg && <Alert msg={msg} type={msg.includes('cancel') ? 'ok' : 'error'}/>}

      {canCancel && (
        <button
          style={{ ...css.btn, background:G.redBg, border:`1px solid ${G.redBdr}`, color:G.red, marginTop:4, opacity: cancelling ? 0.6 : 1 }}
          onClick={cancelJob} disabled={cancelling}>
          {cancelling ? 'Cancelling…' : 'Cancel job'}
        </button>
      )}

      <div style={{ textAlign:'center', marginTop:16 }}>
        <span style={{ fontSize:12, color:G.text3 }}>Page auto-refreshes every 8 seconds</span>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   SHOPS
══════════════════════════════════════════════════════════════════════════ */
function ShopsScreen() {
  const [shops, setShops] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get('/shops/nearby/').then(r => setShops(r.data.shops || [])).finally(() => setLoading(false));
  }, []);

  return (
    <div style={css.page}>
      <div style={css.pageTitle}>Shops near me</div>
      {loading ? <Spinner/> : shops.length === 0 ? (
        <div style={{ textAlign:'center', padding:60, color:G.text3 }}>
          <div style={{ fontSize:48 }}>📍</div>
          <div style={{ fontSize:14, marginTop:12 }}>No shops online right now</div>
        </div>
      ) : shops.map(s => (
        <div key={s.id} style={{ ...css.card, marginBottom:8 }}>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
            <div style={{ fontWeight:700, color:G.text, fontSize:15 }}>{s.name}</div>
            <span style={{ ...css.badge, background: s.is_online ? G.greenBg : '#1A1A1A', color: s.is_online ? G.green : G.text3 }}>
              {s.is_online ? '● Online' : '○ Offline'}
            </span>
          </div>
          <div style={{ fontSize:13, color:G.text3, marginTop:4 }}>{s.address}</div>
          <div style={{ display:'flex', justifyContent:'space-between', marginTop:10, fontSize:12 }}>
            <span style={{ color: s.queue_length >= 20 ? G.red : s.queue_length >= 14 ? G.amber : G.text3 }}>
              Queue: {s.queue_length}/20
              {s.queue_length >= 20 ? ' · FULL' : s.queue_length >= 14 ? ' · Busy' : ' · Available'}
            </span>
            <span style={{ color:G.text3 }}>⏰ {s.opens_at}–{s.closes_at}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

