/* ═══════════════════════════════════════════════════════════════════════════
   ROOT — navigation controller
══════════════════════════════════════════════════════════════════════════ */
export default function App() {
  const [user,      setUser]      = useState(() => {
    try { return JSON.parse(localStorage.getItem('user') || 'null'); } catch { return null; }
  });
  const [page,      setPage]      = useState('login');
  const [tab,       setTab]       = useState('home');
  const [navParams, setNavParams] = useState(null);  // payload passed between screens

  useEffect(() => {
    if (localStorage.getItem('token') && user) setPage('app');
  }, []);

  const handleLogin  = (u) => { setUser(u); setPage('app'); setTab('home'); };
  const handleLogout = ()  => { localStorage.clear(); setUser(null); setPage('login'); };

  // navigate(dest, params) — params are passed to the target screen
  const navigate = useCallback((dest, params = null) => {
    setNavParams(params);
    setTab(dest);
  }, []);

  if (page === 'login')    return <div style={css.app}><LoginScreen    onLogin={handleLogin} onGoRegister={() => setPage('register')}/></div>;
  if (page === 'register') return <div style={css.app}><RegisterScreen onLogin={handleLogin} onGoLogin={()    => setPage('login')}/></div>;

  const mainTabs = ['home','jobs','shops','profile'];

  const renderTab = () => {
    if (tab === 'newjob')   return <NewJobScreen    onNav={navigate}/>;
    if (tab === 'checkout')  return <CheckoutScreen  params={navParams} user={user} onNav={navigate}/>;
    if (tab === 'jobdetail') return <JobDetailScreen job={navParams}   user={user} onNav={navigate}/>;
    if (tab === 'pickupid')  return <PickupIDScreen  user={user} onBack={() => setTab('home')}/>;
    if (tab === 'jobs')      return <JobsScreen      onNav={navigate}/>;
    if (tab === 'shops')     return <ShopsScreen/>;
    if (tab === 'profile')   return <ProfileScreen   user={user} onLogout={handleLogout} onNav={navigate}/>;
    return <HomeScreen user={user} onNav={navigate}/>;
  };

  return (
    <div style={css.app}>
      <div style={css.nav}>
        <div style={css.navBrand}>🖨️ PrintShop</div>
        <div style={{ display:'flex', alignItems:'center', gap:12 }}>
          <div style={{ fontSize:13, color:G.text3 }}>{user.name.split(' ')[0]}</div>
          <div style={{ width:32, height:32, borderRadius:16, background:G.greenBg, display:'flex', alignItems:'center', justifyContent:'center', fontSize:14, fontWeight:800, color:G.green, cursor:'pointer' }}
            onClick={() => navigate('profile')}>
            {user.name[0].toUpperCase()}
          </div>
        </div>
      </div>

      {renderTab()}

      {mainTabs.includes(tab) && <TabBar active={tab} onNav={navigate}/>}
    </div>
  );
}
